package org.mage.test.cards.single.msh;

import mage.constants.PhaseStep;
import mage.constants.SubType;
import mage.constants.Zone;
import org.junit.Test;
import org.mage.test.serverside.base.CardTestPlayerBase;

/**
 * {@link mage.cards.u.UndercoverSkrull Undercover Skrull} {1}{G}
 * As long as there are two or more creature cards in your graveyard, this creature
 * gets +2/+2 and is all creature types.
 * <p>
 * CR 611.3a: an effect generated by a static ability isn't locked in, so a false
 * condition must not discard it permanently.
 */
public class UndercoverSkrullTest extends CardTestPlayerBase {

    private static final String skrull = "Undercover Skrull";

    @Test
    public void test_AllTypesAppliesAfterConditionWasFalse() {
        setStrictChooseMode(true);

        addCard(Zone.BATTLEFIELD, playerA, skrull);
        addCard(Zone.BATTLEFIELD, playerA, "Memnite");
        addCard(Zone.BATTLEFIELD, playerA, "Ornithopter");
        addCard(Zone.BATTLEFIELD, playerA, "Mountain", 2);
        addCard(Zone.HAND, playerA, "Lightning Bolt", 2);

        // empty graveyard: the condition is false and layers are applied
        checkPT("1/1 at start", 1, PhaseStep.PRECOMBAT_MAIN, playerA, skrull, 1, 1);

        castSpell(1, PhaseStep.POSTCOMBAT_MAIN, playerA, "Lightning Bolt", "Memnite");
        castSpell(1, PhaseStep.POSTCOMBAT_MAIN, playerA, "Lightning Bolt", "Ornithopter");

        setStopAt(1, PhaseStep.END_TURN);
        execute();

        assertGraveyardCount(playerA, "Memnite", 1);
        assertGraveyardCount(playerA, "Ornithopter", 1);
        assertPowerToughness(playerA, skrull, 3, 3);
        assertSubtype(skrull, SubType.WIZARD);
        assertSubtype(skrull, SubType.SKRULL);
    }
}
